import {selectInvoiceCredit} from './invoice-credit-options';
type Scope={tenant:string;property:string;invoice:string;actor:string};
type Store=Pick<Storage,'getItem'|'setItem'|'removeItem'>;
function pendingKey(scope:Scope){if(!Object.values(scope).every(v=>/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(v)))throw Error('Invalid credit workspace.');return 'irp.invoice.credit.v1:'+ [scope.tenant,scope.property,scope.invoice,scope.actor].join(':');}
function validateSaved(value:unknown,scope:Scope):ReturnType<typeof prepareInvoiceCredit>{
 const r=value as ReturnType<typeof prepareInvoiceCredit>,a=r?.args;
 if(!a||r.actor!==scope.actor||a.p_tenant!==scope.tenant||a.p_property!==scope.property||a.p_invoice!==scope.invoice||typeof a.p_request!=='string'||!/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(a.p_request)||a.p_confirmed!==true||typeof a.p_reason!=='string'||a.p_reason!==a.p_reason.trim()||a.p_reason.length<4||a.p_reason.length>500||Array.from(a.p_reason).some(c=>c.charCodeAt(0)<32||c.charCodeAt(0)===127)||typeof a.p_effective_on!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(a.p_effective_on)||!Number.isFinite(Date.parse(a.p_effective_on+'T00:00:00Z'))||new Date(a.p_effective_on+'T00:00:00Z').toISOString().slice(0,10)!==a.p_effective_on||!Array.isArray(a.p_lines)||!a.p_lines.length||a.p_lines.length>10000)throw Error('Invalid saved credit request. Preserve it for recovery.');
 const seen=new Set<number>();let total=BigInt(0);const lines=a.p_lines.map(l=>{if(!l||!Number.isInteger(l.line_number)||l.line_number<1||l.line_number>10000||seen.has(l.line_number)||typeof l.amount_minor!=='string'||!/^[1-9][0-9]{0,11}$/.test(l.amount_minor))throw Error('Invalid saved credit lines.');seen.add(l.line_number);total+=BigInt(l.amount_minor);return {line_number:l.line_number,amount_minor:l.amount_minor};});if(total>BigInt('999999999999')||r.amount_minor!==total.toString())throw Error('Saved credit total does not reconcile.');
 return {actor:scope.actor,amount_minor:total.toString(),args:{p_tenant:scope.tenant,p_property:scope.property,p_invoice:scope.invoice,p_request:a.p_request,p_effective_on:a.p_effective_on,p_lines:lines,p_reason:a.p_reason,p_confirmed:true}};
}
export function loadPendingCredit(store:Store,scope:Scope){const raw=store.getItem(pendingKey(scope));return raw===null?null:validateSaved(JSON.parse(raw),scope);}
export function savePendingCredit(store:Store,scope:Scope,request:ReturnType<typeof prepareInvoiceCredit>){const saved=validateSaved(request,scope),existing=loadPendingCredit(store,scope),encoded=JSON.stringify(saved);if(existing&&JSON.stringify(existing)!==encoded)throw Error('Resolve the existing credit request first.');store.setItem(pendingKey(scope),encoded);if(store.getItem(pendingKey(scope))!==encoded)throw Error('Unable to preserve credit request.');return saved;}
export function clearPendingCredit(store:Store,scope:Scope,request:string){const existing=loadPendingCredit(store,scope);if(existing&&existing.args.p_request!==request)throw Error('A different credit request is pending.');store.removeItem(pendingKey(scope));if(store.getItem(pendingKey(scope))!==null)throw Error('Unable to clear credit request.');}
export function prepareInvoiceCredit(scope:Scope,request:string,options:unknown,input:{lines:{line_number:number;amount_minor:string}[];effective_on:string;reason:string}){
 const uuid=/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i;if(![...Object.values(scope),request].every(v=>uuid.test(v)))throw Error('Invalid credit request scope.');
 const selected=selectInvoiceCredit(options,scope,input.lines),date=input.effective_on;
 if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(Date.parse(date+'T00:00:00Z'))||new Date(date+'T00:00:00Z').toISOString().slice(0,10)!==date)throw Error('Choose a valid credit date.');
 const reason=input.reason.trim();if(reason.length<4||reason.length>500||Array.from(reason).some(c=>c.charCodeAt(0)<32||c.charCodeAt(0)===127))throw Error('Enter a credit reason between 4 and 500 characters.');
 return {actor:scope.actor,amount_minor:selected.amount_minor,args:{p_tenant:scope.tenant,p_property:scope.property,p_invoice:scope.invoice,p_request:request,p_effective_on:date,p_lines:selected.lines,p_reason:reason,p_confirmed:true}};
}
export function readInvoiceCreditReceipt(value:unknown,request:ReturnType<typeof prepareInvoiceCredit>){const r=value as Record<string,unknown>,a=request.args;if(!r||r.schema_version!==1||r.tenant_id!==a.p_tenant||r.property_id!==a.p_property||r.actor_id!==request.actor||r.request_id!==a.p_request||r.credit_id!==a.p_request||r.invoice_id!==a.p_invoice||r.amount_minor!==request.amount_minor||r.effective_on!==a.p_effective_on||r.reason!==a.p_reason||typeof r.replayed!=='boolean'||typeof r.number!=='string'||!/^[1-9][0-9]{0,11}$/.test(r.number))throw Error('Credit receipt does not match the reviewed request.');return {credit_id:a.p_request,number:r.number,amount_minor:request.amount_minor,replayed:r.replayed};}
